SELECT COUNT(*)
FROM account
WHERE DATE_FORMAT(created_at, '%Y%m%d') = #{datePart}

SELECT count(*)
FROM account
WHERE account_id = #{account_id};

SELECT name
FROM users
WHERE user_id = #{userId}

select count(*)
from account_member
where user_id = #{userId}
  and account_id = #{accountId};

select count(*)
from account
where account_id = #{accountId}
  and account_type = "group";

SELECT count(*)
FROM account
WHERE account_id = #{account_id};

select count(*)
from account
where account_id = #{accountId}
  and is_deleted = 'N';
